"""Check both invocations of the resource-warning script generated by the original parent."""
import ast
import hashlib
import json
import textwrap


def verify(root, tag, label, results):
    key = "test.test_warnings.PyWarningsDisplayTests.test_tracemalloc"
    assert list(results) == [key] and results[key]["paired"]
    suite = root / "pinned-source/Lib/test/test_warnings/__init__.py"
    tree = ast.parse(suite.read_text())
    cls, = [node for node in tree.body if isinstance(node, ast.ClassDef) and node.name == "PyWarningsDisplayTests"]
    method, = [node for node in cls.body if isinstance(node, ast.FunctionDef) and node.name == "test_tracemalloc"]
    write, = [node for node in ast.walk(method) if isinstance(node, ast.Call)
              and isinstance(node.func, ast.Attribute) and node.func.attr == "write"]
    (dedent,) = write.args
    assert isinstance(dedent.func, ast.Attribute) and dedent.func.attr == "dedent"
    script = textwrap.dedent(ast.literal_eval(dedent.args[0]))
    script_hash = hashlib.sha256(script.encode()).hexdigest()

    for level in ("O0", "O3"):
        folder = root / tag / f"children-{level}-{label}"
        process = json.loads((folder / f"{label}.json").read_bytes())
        group = [json.loads(s) for s in (folder / "process-group.jsonl").read_text().splitlines()]
        records = [json.loads(s) for s in (folder / "tracemalloc-argv.jsonl").read_text().splitlines()]
        paired_pids = results[key][level]["children"]["matched_workload_pids"]
        workloads = [r for r in records if r["pid"] in paired_pids]
        assert len(workloads) == len(paired_pids) == 2
        assert workloads[0]["argv"][-1] == workloads[1]["argv"][-1]
        # The stock case invokes the file first with tracing disabled and then with a limit of 2.
        expected = [["-X", "faulthandler", "-Wd"],
                    ["-X", "faulthandler", "-Wd", "-X", "tracemalloc=2"]]
        for run, options in zip(workloads, expected):
            assert run["case"] == key and run["argv"][0] == process["argv"][0]
            assert run["argv"][1:-1] == options
            assert run["script_text"] == script and run["script_sha256"] == script_hash
            observed, = [event for event in group if event["phase"] == key
                         and event["kind"] == "native-driver" and event["pid"] == run["pid"]]
            digest = hashlib.sha256("\0".join(run["argv"]).encode()).hexdigest()
            assert run["argv_sha256"] == observed["argv_sha256"] == digest
